INSERT INTO blog_articles (
  slug, title_el, title_en, excerpt_el, excerpt_en,
  content_el, content_en, category, image_url, author,
  read_time_min, tags, related_area_slugs, related_beach_slugs,
  related_listing_slugs, related_article_slugs, published_at
) VALUES (
  'ammouliani-island-complete-guide',
  'Αμμουλιανή: Πλήρης Οδηγός για το Νησί της Χαλκιδικής',
  'Ammouliani: Complete Guide to Halkidiki''s Island',
  'Ανακαλύψτε την Αμμουλιανή, το μοναδικό κατοικημένο νησί της Χαλκιδικής. Παραλίες, ταβέρνες, φέρι και συμβουλές διαμονής.',
  'Discover Ammouliani, Halkidiki''s only inhabited island. Beaches, tavernas, ferry info, and accommodation tips.',
  E'## Αμμουλιανή: Το Μικρό Νησί με τη Μεγάλη Γοητεία\n\nΗ Αμμουλιανή είναι το μοναδικό κατοικημένο νησί της Χαλκιδικής και βρίσκεται στον κόλπο του Αγίου Όρους, απέναντι από τη Χερσόνησο του Άθω. Με μόλις 4,5 τετραγωνικά χιλιόμετρα έκταση, αυτό το μικρό νησί προσφέρει μια αυθεντική νησιωτική εμπειρία χωρίς τον συνωστισμό των μεγάλων τουριστικών νησιών.\n\n## Πώς να Φτάσετε\n\nΗ πρόσβαση στην Αμμουλιανή γίνεται αποκλειστικά με φέρι από το λιμανάκι της Τρυπητής, που βρίσκεται περίπου 120 χιλιόμετρα από τη Θεσσαλονίκη. Τα δρομολόγια εκτελούνται καθημερινά, με συχνότητα κάθε 30-45 λεπτά κατά τους καλοκαιρινούς μήνες. Η διαδρομή διαρκεί περίπου 10 λεπτά. Μπορείτε να πάρετε και το αυτοκίνητό σας στο φέρι, αν και το νησί είναι αρκετά μικρό για να το εξερευνήσετε με τα πόδια ή με ενοικιαζόμενο ποδήλατο. Τα εισιτήρια κοστίζουν περίπου 2-3 ευρώ για πεζούς και 10-15 ευρώ για αυτοκίνητο.\n\n## Οι Παραλίες\n\n### Αλυκές\nΗ πιο διάσημη παραλία του νησιού, με χρυσή αμμουδιά και ρηχά τιρκουάζ νερά. Βρίσκεται στη νοτιοδυτική πλευρά και είναι οργανωμένη με ξαπλώστρες και καντίνα. Ιδανική για οικογένειες λόγω των ρηχών νερών.\n\n### Μεγάλη Άμμος\nΜια μεγάλη αμμώδης παραλία κοντά στον οικισμό. Εύκολα προσβάσιμη, με αρκετές ταβέρνες σε κοντινή απόσταση. Τα νερά είναι καθαρά και σχετικά ήρεμα.\n\n### Άγιος Γεώργιος\nΜια ήσυχη παραλία στην ανατολική πλευρά του νησιού. Λιγότερο οργανωμένη, ιδανική για όσους αναζητούν ησυχία. Θέα προς το Άγιο Όρος.\n\n### Κάρβουνα και Τσάσκα\nΜικρότερες, απομονωμένες παραλίες που προσεγγίζονται κυρίως με βάρκα ή μέσω μονοπατιών. Ιδανικές για ήρεμες εξορμήσεις.\n\n## Φαγητό και Ταβέρνες\n\nΤο χωριό της Αμμουλιανής έχει αρκετές παραδοσιακές ταβέρνες που σερβίρουν φρέσκα θαλασσινά. Δοκιμάστε τα μύδια Αμμουλιανής, που θεωρούνται από τα καλύτερα της περιοχής, καθώς υπάρχουν μυδοκαλλιέργειες στον κόλπο. Οι γαρίδες σχάρας και τα χταπόδια είναι επίσης εξαιρετικά. Μην παραλείψετε να δοκιμάσετε το τοπικό τσίπουρο που συνοδεύει τέλεια τους μεζέδες.\n\n## Διαμονή\n\nΗ Αμμουλιανή προσφέρει διάφορες επιλογές διαμονής: μικρά ξενοδοχεία, ενοικιαζόμενα δωμάτια και studios. Κρατήσεις νωρίς είναι απαραίτητες για τον Ιούλιο και τον Αύγουστο, καθώς η ζήτηση είναι υψηλή. Οι τιμές κυμαίνονται από 50 έως 120 ευρώ τη βραδιά, ανάλογα με την περίοδο.\n\n## Λίγη Ιστορία\n\nΗ Αμμουλιανή ανήκε στη Μονή Βατοπεδίου του Αγίου Όρους μέχρι το 1924, όταν εγκαταστάθηκαν πρόσφυγες από τη Μικρά Ασία. Η ιστορία αυτή δίνει στο νησί μια ιδιαίτερη πολιτιστική ταυτότητα που μπορείτε να νιώσετε στην αρχιτεκτονική και τις παραδόσεις.\n\n## Καλύτερη Περίοδος Επίσκεψης\n\nΟ Ιούνιος και ο Σεπτέμβριος είναι ιδανικοί μήνες. Η θάλασσα είναι ζεστή, οι τιμές πιο προσιτές και η ατμόσφαιρα πιο χαλαρή. Τον Ιούλιο και τον Αύγουστο το νησί γεμίζει, αλλά η ζωντάνια του αξίζει.\n\n## Πρακτικές Συμβουλές\n\n- Φέρτε μετρητά, καθώς δεν δέχονται όλα τα καταστήματα κάρτα\n- Ενοικιάστε ποδήλατο για να εξερευνήσετε το νησί\n- Κάντε κρουαζιέρα γύρω από το νησί για να δείτε κρυφές παραλίες\n- Επισκεφτείτε την εκκλησία του Αγίου Νικολάου στο κέντρο του χωριού\n- Απολαύστε το ηλιοβασίλεμα από τη δυτική ακτή με θέα προς τη Σιθωνία',
  E'## Ammouliani: Halkidiki''s Hidden Island Gem\n\nAmmouliani is the only inhabited island in Halkidiki, located in the gulf near Mount Athos. Covering just 4.5 square kilometers, this small island offers an authentic Greek island experience without the overcrowding.\n\n## Getting There\n\nThe only way to reach Ammouliani is by ferry from Tripiti port, about 120 km from Thessaloniki. Ferries run every 30-45 minutes in summer, and the crossing takes roughly 10 minutes. You can bring your car, though the island is small enough to explore on foot or by rented bicycle. Tickets cost around 2-3 euros for pedestrians and 10-15 euros for cars.\n\n## Beaches\n\n**Alykes** is the island''s most famous beach, featuring golden sand and shallow turquoise waters. It is organized with sunbeds and a canteen, making it ideal for families.\n\n**Megali Ammos** is a large sandy beach near the village, easily accessible with tavernas nearby.\n\n**Agios Georgios** is a quieter beach on the eastern side, offering views toward Mount Athos.\n\nSmaller coves like Karvouna and Tsaska are best reached by boat, perfect for a peaceful escape.\n\n## Food\n\nThe village has excellent traditional tavernas serving fresh seafood. Try the local mussels, which are farmed in the surrounding bay and considered among the best in the region. Grilled shrimp and octopus are also outstanding. Local tsipouro pairs perfectly with meze.\n\n## Accommodation\n\nOptions include small hotels, studios, and rooms for rent, ranging from 50 to 120 euros per night. Book early for July and August, as demand is very high.\n\n## History\n\nAmmouliani belonged to the Vatopedi Monastery on Mount Athos until 1924, when Asia Minor refugees settled here. This gives the island a unique cultural identity visible in its architecture and traditions.\n\n## Best Time to Visit\n\nJune and September offer warm seas, lower prices, and a more relaxed atmosphere. July and August are lively but crowded.\n\n## Tips\n\n- Bring cash as not all shops accept cards\n- Rent a bicycle to explore the island\n- Take a boat tour to discover hidden coves\n- Watch the sunset from the western coast facing Sithonia',
  'guides',
  '',
  'ChalkidikiHub',
  7,
  '["ammouliani","island","ferry","athos","beaches","halkidiki"]'::jsonb,
  '["athos"]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '2026-03-15'
);

INSERT INTO blog_articles (
  slug, title_el, title_en, excerpt_el, excerpt_en,
  content_el, content_en, category, image_url, author,
  read_time_min, tags, related_area_slugs, related_beach_slugs,
  related_listing_slugs, related_article_slugs, published_at
) VALUES (
  'afytos-village-guide',
  'Αφύτος: Το Πιο Όμορφο Χωριό της Κασσάνδρας',
  'Afytos: The Most Beautiful Village of Kassandra',
  'Ανακαλύψτε τον Αφύτο, το πέτρινο στολίδι της Κασσάνδρας με πανοραμική θέα, ιστορία και αυθεντική γοητεία.',
  'Discover Afytos, Kassandra''s stone jewel with panoramic views, ancient history, and authentic Greek charm.',
  E'## Αφύτος: Το Πέτρινο Στολίδι της Κασσάνδρας\n\nΟ Αφύτος (ή Άφυτος) είναι ένα από τα πιο γραφικά χωριά της Χαλκιδικής και σίγουρα το ομορφότερο της Κασσάνδρας. Χτισμένο πάνω σε βράχο με θέα τον Θερμαϊκό κόλπο, ξεχωρίζει για τα πέτρινα σπίτια, τα λιθόστρωτα σοκάκια και την αυθεντική ατμόσφαιρά του.\n\n## Αρχιτεκτονική και Πέτρινα Σπίτια\n\nΟ Αφύτος είναι ένας από τους λίγους παραδοσιακούς οικισμούς της Κασσάνδρας που έχει διατηρήσει την αρχιτεκτονική του κληρονομιά. Τα πέτρινα σπίτια χρονολογούνται κυρίως από τον 19ο αιώνα και έχουν αναπαλαιωθεί με σεβασμό στην παράδοση. Πολλά από αυτά λειτουργούν σήμερα ως ξενώνες, εστιατόρια και μαγαζιά. Περπατώντας στα σοκάκια θα αισθανθείτε ότι ταξιδεύετε στο χρόνο.\n\n## Η Πλατεία και η Θέα\n\nΗ κεντρική πλατεία του Αφύτου βρίσκεται στην άκρη του βράχου και προσφέρει μια από τις πιο εντυπωσιακές θέες στη Χαλκιδική. Από εκεί βλέπετε ολόκληρο τον Θερμαϊκό κόλπο, το βουνό Όλυμπος τις καθαρές μέρες, και τα απέραντα γαλανά νερά. Το ηλιοβασίλεμα από εδώ είναι μαγικό και αποτελεί καθημερινό τελετουργικό για ντόπιους και επισκέπτες.\n\n## Ο Αριστοτέλης και η Αρχαία Ιστορία\n\nΣτην πλατεία υπάρχει ένα αντίγραφο αρχαίου αγάλματος και ρητά του Αριστοτέλη, υπενθυμίζοντας τη βαθιά σχέση της Χαλκιδικής με τον μεγάλο φιλόσοφο. Στην περιοχή βρίσκονται ερείπια αρχαίου ναού της Αθηνάς, που αποδεικνύουν τη σημασία του οικισμού στην αρχαιότητα. Ο αρχαίος Αφύτος αναφέρεται από τον Ηρόδοτο και τον Θουκυδίδη.\n\n## Ταβέρνες και Φαγητό\n\nΟ Αφύτος φημίζεται για τις ταβέρνες του:\n\n- **Μαρίνα**: Κλασική ψαροταβέρνα με θέα τη θάλασσα. Φρέσκα ψάρια και θαλασσινά σε εξαιρετικές τιμές.\n- **Κληματαριά**: Παραδοσιακή ταβέρνα σε πέτρινο κτίριο με αυλή. Μαγειρευτά φαγητά, κρέατα στα κάρβουνα και τοπικό κρασί.\n- Εκτός από τις ταβέρνες, θα βρείτε μοντέρνα καφέ και μπαρ που ανοίγουν μέχρι αργά, ιδιαίτερα κατά μήκος του βράχου.\n\n## Το Φεστιβάλ Κασσανδρινό\n\nΚάθε καλοκαίρι, ο Αφύτος φιλοξενεί εκδηλώσεις στο πλαίσιο του Φεστιβάλ Κασσανδρινό, με μουσικές, θεατρικές και πολιτιστικές παραστάσεις. Οι εκδηλώσεις γίνονται στο υπαίθριο θέατρο και σε διάφορα σημεία του χωριού, δίνοντας μια ιδιαίτερη πνοή στις καλοκαιρινές βραδιές.\n\n## Παραλίες\n\nΚάτω από τον βράχο του Αφύτου βρίσκεται μια μεγάλη αμμώδης παραλία με καθαρά νερά. Η πρόσβαση γίνεται από σκαλοπάτια ή μέσω δρόμου. Η παραλία είναι εν μέρει οργανωμένη και αρκετά ευρύχωρη ακόμα και τον Αύγουστο.\n\n## Πρακτικές Συμβουλές\n\n- Περπατήστε στα σοκάκια χωρίς χάρτη και αφεθείτε να χαθείτε\n- Επισκεφτείτε το Λαογραφικό Μουσείο για την ιστορία του χωριού\n- Πάρτε τον καφέ σας στην πλατεία νωρίς το πρωί για ήρεμη ατμόσφαιρα\n- Παρκάρετε στο πάρκινγκ εκτός χωριού τους καλοκαιρινούς μήνες\n- Δοκιμάστε τα τοπικά γλυκά στα ζαχαροπλαστεία της πλατείας',
  E'## Afytos: Kassandra''s Stone-Built Gem\n\nAfytos is one of Halkidiki''s most picturesque villages and arguably the most beautiful on the Kassandra peninsula. Built on a cliff overlooking the Thermaic Gulf, it stands out for its stone houses, cobbled lanes, and authentic atmosphere.\n\n## Architecture\n\nAfytos is one of the few traditional settlements in Kassandra that has preserved its architectural heritage. The stone houses mostly date from the 19th century and have been respectfully restored. Many now operate as guesthouses, restaurants, and shops. Walking through the alleys feels like stepping back in time.\n\n## The Square and the View\n\nThe central square sits at the cliff edge, offering one of the most impressive views in Halkidiki. On clear days, you can see Mount Olympus across the Thermaic Gulf. The sunset here is magical and draws both locals and visitors every evening.\n\n## Ancient History\n\nThe square features a replica of an ancient statue with quotes from Aristotle, highlighting Halkidiki''s deep philosophical heritage. Nearby stand the ruins of an ancient Temple of Athena. Ancient Afytos is mentioned by both Herodotus and Thucydides.\n\n## Tavernas\n\n**Marina** is a classic fish taverna with sea views, serving fresh fish at excellent prices. **Klimataria** occupies a stone building with a courtyard, offering home-cooked dishes, grilled meats, and local wine. Modern cafes and bars line the clifftop and stay open late.\n\n## Kassandrino Festival\n\nEach summer, Afytos hosts events as part of the Kassandrino Festival featuring music, theater, and cultural performances at the open-air theater and around the village.\n\n## Beach\n\nBelow the cliff lies a large sandy beach with clean waters, reached via stairs or a road. It is partly organized and spacious even in August.\n\n## Tips\n\n- Wander the lanes without a map and enjoy getting lost\n- Visit the Folklore Museum\n- Have morning coffee at the square before the crowds\n- Park outside the village in summer\n- Try local sweets at the pastry shops on the square',
  'guides',
  '',
  'ChalkidikiHub',
  6,
  '["afytos","village","kassandra","traditional","architecture","sunset"]'::jsonb,
  '["kassandra"]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '2026-03-10'
);

