INSERT INTO blog_articles (
  slug, title_el, title_en, excerpt_el, excerpt_en,
  content_el, content_en, category, image_url, author,
  read_time_min, tags, related_area_slugs, related_beach_slugs,
  related_listing_slugs, related_article_slugs, published_at
) VALUES (
  'kavourotripes-secret-beach',
  'Καβουρότρυπες: Η Πιο Εξωτική Παραλία της Σιθωνίας',
  'Kavourotripes: Sithonia''s Most Exotic Beach',
  'Ανακαλύψτε τις Καβουρότρυπες, τους κρυφούς πορτοκαλί κόλπους της Σιθωνίας με κρυστάλλινα νερά και εξωτική ομορφιά.',
  'Discover Kavourotripes, Sithonia''s hidden orange-sand coves with crystal-clear waters and exotic beauty.',
  E'## Καβουρότρυπες: Ένα Κρυμμένο Παράδεισο\n\nΟι Καβουρότρυπες (ή Portokali Beach / Orange Beach) βρίσκονται στη νοτιοανατολική ακτή της Σιθωνίας, ανάμεσα στη Σάρτη και τους Συκιά. Πρόκειται για μια σειρά μικρών κόλπων με πορτοκαλί αμμουδιά, λευκούς βράχους και απίστευτα καθαρά τιρκουάζ νερά. Δεν είναι υπερβολή να πούμε ότι μοιάζουν με καραϊβική παραλία.\n\n## Πώς να Φτάσετε\n\nΗ πρόσβαση στις Καβουρότρυπες απαιτεί λίγη προσπάθεια, κάτι που τις κρατάει σχετικά ήσυχες. Από τον κεντρικό δρόμο Σάρτη-Συκιά, στρίβετε σε χωματόδρομο που σημαδεύεται με μικρές πινακίδες. Ο χωματόδρομος είναι περίπου 2 χιλιόμετρα και σε μέτρια κατάσταση. Μπορείτε να τον περάσετε με κανονικό αυτοκίνητο αν οδηγείτε αργά. Στο τέλος υπάρχει ανεπίσημο πάρκινγκ.\n\n## Οι Κόλποι\n\nΟι Καβουρότρυπες αποτελούνται από πέντε ή έξι μικρούς κόλπους χωρισμένους από βράχια. Ο κάθε κόλπος χωράει λίγες δεκάδες ανθρώπους, δημιουργώντας μια αίσθηση ιδιωτικότητας. Η άμμος έχει ένα μοναδικό πορτοκαλί-χρυσό χρώμα και τα νερά είναι αβαθή στην αρχή και μετά βαθαίνουν.\n\n## Nudist Section\n\nΟ τελευταίος κόλπος (ο πιο απομονωμένος) χρησιμοποιείται παραδοσιακά ως γυμνιστική παραλία. Δεν υπάρχει επίσημη σήμανση, αλλά αν δεν σας ενδιαφέρει, μείνετε στους πρώτους κόλπους.\n\n## Τι να Προσέξετε\n\n- **Καμία οργάνωση**: Δεν υπάρχουν ξαπλώστρες, ντους, ή τουαλέτες. Φέρτε τα πάντα μαζί σας.\n- **Σκιά**: Ελάχιστη φυσική σκιά. Ομπρέλα θαλάσσης είναι απαραίτητη.\n- **Νερό και φαγητό**: Το πλησιέστερο μαγαζί είναι αρκετά μακριά. Φέρτε αρκετό νερό και σνακ.\n- **Σκουπίδια**: Πάρτε τα σκουπίδια σας μαζί σας. Η παραλία δεν έχει κάδους.\n- **Παπούτσια θαλάσσης**: Χρήσιμα για τους βράχους μεταξύ των κόλπων.\n\n## Κολύμβηση με Μάσκα\n\nΤα βράχια γύρω από τους κόλπους προσφέρουν εξαιρετική ευκαιρία για snorkeling. Η ορατότητα φτάνει τα 10-15 μέτρα και θα δείτε αχινούς, μικρά ψάρια και ανεμώνες.\n\n## Πότε να Πάτε\n\nΕπισκεφτείτε νωρίς το πρωί ή αργά το απόγευμα. Τον Ιούλιο και τον Αύγουστο, οι κόλποι γεμίζουν γρήγορα μετά τις 11. Τον Ιούνιο και τον Σεπτέμβριο, η εμπειρία είναι πολύ πιο ήρεμη.\n\n## Γύρω από τις Καβουρότρυπες\n\nΑν θέλετε εναλλακτικές, κοντά βρίσκονται η παραλία Φυκιάδα και η Λαγομάνδρα. Η Σάρτη, σε απόσταση 10 λεπτών, έχει σούπερ μάρκετ, εστιατόρια και όλες τις παροχές.',
  E'## Kavourotripes: A Hidden Paradise\n\nKavourotripes (also known as Portokali Beach or Orange Beach) sits on the southeastern coast of Sithonia, between Sarti and Sykia. It is a series of small coves featuring orange sand, white rocks, and incredibly clear turquoise water that rivals Caribbean beaches.\n\n## Getting There\n\nFrom the main Sarti-Sykia road, turn onto a dirt track marked with small signs. The road is about 2 kilometers long and in moderate condition. A regular car can handle it at low speed. An unofficial parking area awaits at the end.\n\n## The Coves\n\nKavourotripes consists of five or six small coves separated by rocks. Each holds a few dozen people, creating a sense of privacy. The sand has a unique orange-gold color, and the water starts shallow before gradually deepening.\n\n## Nudist Section\n\nThe last and most isolated cove is traditionally used as a nudist beach. There is no official signage. If this is not your preference, stay in the first few coves.\n\n## What to Know\n\n- **No facilities**: No sunbeds, showers, or toilets. Bring everything you need.\n- **Shade**: Very little natural shade. A beach umbrella is essential.\n- **Supplies**: The nearest shop is far away. Bring plenty of water and snacks.\n- **Trash**: Take all rubbish with you. There are no bins.\n- **Water shoes**: Useful for walking between coves over rocks.\n\n## Snorkeling\n\nThe rocks around the coves offer excellent snorkeling with visibility reaching 10-15 meters. You will spot sea urchins, small fish, and anemones.\n\n## When to Go\n\nVisit early morning or late afternoon. In July and August the coves fill quickly after 11 AM. June and September offer a much calmer experience.\n\n## Nearby\n\nAlternatives nearby include Fykiada and Lagomandra beaches. Sarti, 10 minutes away, has supermarkets, restaurants, and all amenities.',
  'beaches',
  '',
  'ChalkidikiHub',
  5,
  '["kavourotripes","exotic","sithonia","hidden","nudist","nature"]'::jsonb,
  '["sithonia"]'::jsonb,
  '["sarti-sithonia"]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '2026-03-20'
);

INSERT INTO blog_articles (
  slug, title_el, title_en, excerpt_el, excerpt_en,
  content_el, content_en, category, image_url, author,
  read_time_min, tags, related_area_slugs, related_beach_slugs,
  related_listing_slugs, related_article_slugs, published_at
) VALUES (
  'best-beaches-shallow-water',
  'Παραλίες με Ρηχά Νερά στη Χαλκιδική: Ιδανικές για Παιδιά',
  'Shallow Water Beaches in Halkidiki: Perfect for Kids',
  'Οι καλύτερες παραλίες με ρηχά νερά στη Χαλκιδική για ασφαλές κολύμπι με μικρά παιδιά και όλη την οικογένεια.',
  'The best shallow water beaches in Halkidiki for safe swimming with small children and the whole family.',
  E'## Παραλίες με Ρηχά Νερά: Ο Οδηγός για Οικογένειες\n\nΗ Χαλκιδική είναι ιδανικός προορισμός για οικογένειες με μικρά παιδιά, χάρη στις πολλές παραλίες με ρηχά, ζεστά και ήρεμα νερά. Εδώ σας παρουσιάζουμε τις καλύτερες επιλογές ανά περιοχή.\n\n## Σάνη, Κασσάνδρα\n\nΗ παραλία της Σάνης είναι μια μεγάλη αμμουδιά με εξαιρετικά ρηχά νερά. Μπορείτε να περπατήσετε δεκάδες μέτρα μέσα στη θάλασσα και το νερό να φτάνει μόλις στα γόνατα. Η περιοχή είναι οργανωμένη με ξαπλώστρες, beach bar, και παιδότοπο. Το Sani Resort βρίσκεται δίπλα, αλλά η παραλία είναι ελεύθερη και δημόσια. Ιδανική για παιδιά κάτω των 5 ετών.\n\n## Ποσείδι, Κασσάνδρα\n\nΤο Ποσείδι βρίσκεται στο νοτιοδυτικό άκρο της Κασσάνδρας, σε ένα ακρωτήρι που δημιουργεί δύο παραλίες. Η κυρίως παραλία έχει πολύ ρηχά νερά και λεπτή άμμο. Η περιοχή είναι γνωστή για τον αρχαίο ναό του Ποσειδώνα, τα ερείπια του οποίου βρίσκονται δίπλα στην παραλία. Υπάρχουν ξαπλώστρες, ταβέρνες και μίνι μάρκετ.\n\n## Βουρβουρού, Σιθωνία\n\nΗ Βουρβουρού είναι ένας ήρεμος κόλπος στην ανατολική πλευρά της Σιθωνίας. Τα νερά είναι εξαιρετικά ρηχά και ήρεμα, καθώς ο κόλπος προστατεύεται από τον αέρα. Η θέα στο νησάκι Διάπορος είναι υπέροχη. Οργανωμένη παραλία με ξαπλώστρες και πολλές ταβέρνες στον οικισμό. Το βάθος δεν ξεπερνάει τα 50 εκατοστά για τα πρώτα 30 μέτρα.\n\n## Νέα Ποτίδαια, Κεντρική Χαλκιδική\n\nΗ Νέα Ποτίδαια βρίσκεται στην είσοδο της Κασσάνδρας, στο σημείο που ο Θερμαϊκός συναντά τον Τορωναίο κόλπο. Η αμμώδης παραλία στην πλευρά του Θερμαϊκού έχει πολύ ρηχά νερά και ήρεμη θάλασσα. Κοντά στο κανάλι υπάρχει σύντομη πρόσβαση σε ταβέρνες και καφέ. Ιδανική στάση αν ταξιδεύετε με παιδιά.\n\n## Καλλιθέα, Κασσάνδρα\n\nΗ Καλλιθέα είναι ένα από τα πιο τουριστικά θέρετρα της Κασσάνδρας, με μια μεγάλη αμμώδη παραλία. Τα νερά είναι αρκετά ρηχά, με αμμώδη βυθό χωρίς βράχια. Πλήρως οργανωμένη με ξαπλώστρες, θαλάσσια σπορ, παιδότοπο και πολλές επιλογές φαγητού. Κατάλληλη για οικογένειες που θέλουν ευκολίες.\n\n## Γενικές Συμβουλές για Οικογένειες\n\n- **Αντηλιακό**: Ανανεώνετε κάθε 2 ώρες, ειδικά για τα παιδιά\n- **Ώρες κολύμβησης**: Αποφύγετε τις 12-4 λόγω ήλιου. Πρωί και απόγευμα είναι ιδανικά\n- **Παπουτσάκια θαλάσσης**: Χρήσιμα ακόμα και σε αμμώδεις παραλίες για προστασία από αχινούς\n- **Σκιά**: Προτιμήστε παραλίες με φυσική σκιά ή φέρτε τη δική σας ομπρέλα\n- **Νερό**: Πάντα αρκετό νερό, ειδικά για τα μικρά παιδιά\n\n## Ποια να Διαλέξω;\n\nΑν θέλετε πολλές ευκολίες, επιλέξτε Σάνη ή Καλλιθέα. Αν προτιμάτε ησυχία, η Βουρβουρού είναι η καλύτερη επιλογή. Για στάση στη διαδρομή, η Νέα Ποτίδαια είναι πρακτική.',
  E'## Shallow Water Beaches: The Family Guide\n\nHalkidiki is ideal for families with small children thanks to its many beaches with shallow, warm, and calm waters. Here are the best options by area.\n\n## Sani, Kassandra\n\nSani beach is a large stretch of sand with extremely shallow water. You can walk dozens of meters into the sea with the water barely reaching your knees. The area is organized with sunbeds, a beach bar, and a playground. The Sani Resort is adjacent, but the beach itself is free and public. Ideal for children under 5.\n\n## Possidi, Kassandra\n\nPossidi sits at the southwestern tip of Kassandra on a cape creating two beaches. The main beach has very shallow water and fine sand. The area is known for the ancient Temple of Poseidon, whose ruins stand beside the beach. Sunbeds, tavernas, and a mini market are available.\n\n## Vourvourou, Sithonia\n\nVourvourou is a calm bay on the eastern side of Sithonia. The water is exceptionally shallow and tranquil, as the bay is shielded from wind. The view of Diaporos island is lovely. Depth stays under 50 centimeters for the first 30 meters, making it one of the safest spots for toddlers.\n\n## Nea Potidea, Mainland\n\nLocated at the entrance to Kassandra where the Thermaic and Toroneos gulfs meet, Nea Potidea''s sandy beach on the Thermaic side has very shallow, calm water. Close to tavernas and cafes near the canal, it makes a practical stop when traveling with kids.\n\n## Kallithea, Kassandra\n\nKallithea is one of Kassandra''s busiest resorts, with a large sandy beach and fairly shallow water with a sandy bottom free of rocks. Fully organized with sunbeds, water sports, a playground, and plenty of dining options.\n\n## Tips for Families\n\n- Reapply sunscreen every 2 hours for children\n- Avoid swimming between 12-4 PM due to strong sun\n- Water shoes protect against sea urchins even on sandy beaches\n- Bring your own umbrella if natural shade is scarce\n- Always carry plenty of water for young children',
  'beaches',
  '',
  'ChalkidikiHub',
  6,
  '["shallow","family","kids","safe","beaches","summer"]'::jsonb,
  '["kassandra","sithonia","mainland"]'::jsonb,
  '["sani-kassandra","possidi-kassandra","vourvourou-sithonia","potidea-mainland","kallithea-kassandra"]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '2026-03-05'
);

