INSERT INTO blog_articles (
  slug, title_el, title_en, excerpt_el, excerpt_en,
  content_el, content_en, category, image_url, author,
  read_time_min, tags, related_area_slugs, related_beach_slugs,
  related_listing_slugs, related_article_slugs, published_at
) VALUES (
  'halkidiki-local-products',
  'Τοπικά Προϊόντα Χαλκιδικής: Μέλι, Ελιές, Κρασί',
  'Local Products of Halkidiki: Honey, Olives, Wine',
  'Γνωρίστε τα τοπικά προϊόντα της Χαλκιδικής: τις μεγαλύτερες ελιές της Ελλάδας, αρωματικό μέλι και κρασιά.',
  'Explore Halkidiki''s local products: Greece''s largest olives, aromatic honey, and award-winning local wines.',
  E'## Τοπικά Προϊόντα Χαλκιδικής\n\nΗ Χαλκιδική δεν είναι μόνο παραλίες. Η περιοχή φημίζεται για μια σειρά τοπικών προϊόντων που αντικατοπτρίζουν τον πλούτο του εδάφους και την παράδοση αιώνων.\n\n## Ελιές Χαλκιδικής\n\nΗ ελιά Χαλκιδικής (ποικιλία Χονδρολιά) είναι η μεγαλύτερη ελιά στην Ελλάδα και μια από τις μεγαλύτερες στον κόσμο. Με Προστατευόμενη Γεωγραφική Ένδειξη (ΠΓΕ), αυτές οι πράσινες ελιές ξεχωρίζουν για τη σάρκα τους, τη βουτυρένια υφή και τη χαμηλή οξύτητα. Η συγκομιδή γίνεται κυρίως τον Σεπτέμβριο-Οκτώβριο.\n\nΟι ελιές Χαλκιδικής καταναλώνονται κυρίως ως επιτραπέζιες, γεμιστές με αμύγδαλο, πιπεριά ή σκόρδο. Μπορείτε να τις βρείτε σε τοπικά ελαιοτριβεία και σε παραδοσιακά μαγαζιά σε Αρναία, Νικήτη και Πολύγυρο.\n\n## Ελαιόλαδο\n\nΤο ελαιόλαδο της Χαλκιδικής είναι εξαιρετικό παρθένο, με χαμηλή οξύτητα και φρουτώδη γεύση. Η παραγωγή γίνεται κυρίως στα ορεινά χωριά της κεντρικής Χαλκιδικής. Επισκεφτείτε ένα τοπικό ελαιοτριβείο για να δοκιμάσετε και να αγοράσετε απευθείας.\n\n## Μέλι\n\nΗ Χαλκιδική παράγει εξαιρετικό μέλι χάρη στα πυκνά πευκοδάση και την ποικιλόμορφη χλωρίδα. Τα κυριότερα είδη είναι:\n\n- **Μέλι πεύκου**: Σκούρο, πυκνό, με χαμηλό γλυκαιμικό δείκτη\n- **Μέλι θυμαρίσιο**: Ανοιχτόχρωμο, αρωματικό, με ήπια γεύση\n- **Μέλι ανθέων**: Πολυλουλουδάτο, ιδανικό για μαγειρική\n\nΤο μέλι μπορείτε να το βρείτε σε μελισσοκόμους στην Αρναία, τον Πολύγυρο και τα χωριά της ενδοχώρας. Οι λαϊκές αγορές είναι επίσης καλή πηγή.\n\n## Κρασί\n\nΗ Χαλκιδική έχει αναπτυσσόμενη αμπελουργική παράδοση:\n\n- **Τσάνταλη**: Ένα από τα μεγαλύτερα οινοποιεία της Ελλάδας, με έδρα στο Αγιορείτικο κτήμα. Η ποικιλία Μαλαγουζιά, που σχεδόν εξαφανίστηκε, αναβίωσε εδώ και δίνει αρωματικά λευκά κρασιά.\n- **Πόρτο Καρράς**: Το ιστορικό κτήμα στη Σιθωνία, με αμπελώνες δίπλα στη θάλασσα. Παράγει βραβευμένα κρασιά, ιδιαίτερα τις ποικιλίες Λημνιό και Ασύρτικο.\n- Μικρότερα οινοποιεία στην ενδοχώρα αξίζουν επίσης μια επίσκεψη.\n\n## Τσίπουρο\n\nΤο τσίπουρο είναι αναπόσπαστο μέρος της τοπικής κουλτούρας. Παράγεται από τα στέμφυλα του σταφυλιού και σερβίρεται ως συνοδευτικό μεζέδων. Δοκιμάστε τοπικό τσίπουρο σε ταβέρνες της Νικήτης και του Νέου Μαρμαρά.\n\n## Πού να Αγοράσετε\n\n- **Αρναία**: Λαϊκή αγορά τα Σάββατα, τοπικά μέλια και ελιές\n- **Πολύγυρος**: Καταστήματα τοπικών προϊόντων στην κεντρική αγορά\n- **Νικήτη**: Ελαιοτριβεία και μελισσοκόμοι\n- **Σούπερ μάρκετ**: Βρίσκονται τοπικά προϊόντα, αλλά οι τιμές είναι καλύτερες απευθείας από τους παραγωγούς',
  E'## Local Products of Halkidiki\n\nHalkidiki is not just about beaches. The region is famous for a range of local products reflecting its rich soil and centuries of tradition.\n\n## Halkidiki Olives\n\nThe Halkidiki olive (Chondroelia variety) is the largest olive in Greece and one of the largest in the world. With Protected Geographical Indication (PGI) status, these green olives stand out for their meaty flesh, buttery texture, and low acidity. They are harvested mainly in September and October.\n\nHalkidiki olives are typically consumed as table olives, often stuffed with almonds, peppers, or garlic. Find them at local olive presses and traditional shops in Arnea, Nikiti, and Polygyros.\n\n## Olive Oil\n\nHalkidiki produces excellent extra virgin olive oil with low acidity and a fruity taste, mainly from the mountainous villages of central Halkidiki. Visit a local olive press to taste and buy directly.\n\n## Honey\n\nHalkidiki produces outstanding honey thanks to its dense pine forests and diverse flora. Main types include pine honey (dark, thick, low glycemic), thyme honey (light, aromatic, mild), and wildflower honey (versatile, great for cooking). Find local honey from beekeepers in Arnea, Polygyros, and inland villages.\n\n## Wine\n\n**Tsantali** is one of Greece''s largest wineries, based in the Mount Athos estate. The Malagousia variety, which nearly went extinct, was revived here and produces aromatic white wines. **Porto Carras** in Sithonia grows vineyards by the sea and produces award-winning wines, notably Limnio and Assyrtiko. Smaller wineries in the hinterland are also worth a visit.\n\n## Tsipouro\n\nTsipouro is an essential part of local culture, distilled from grape pomace and served alongside meze. Try local tsipouro at tavernas in Nikiti and Neos Marmaras.\n\n## Where to Buy\n\n- **Arnea**: Saturday market with local honey and olives\n- **Polygyros**: Local product shops in the central market\n- **Nikiti**: Olive presses and beekeepers\n- Buy directly from producers for better prices than supermarkets',
  'food',
  '',
  'ChalkidikiHub',
  6,
  '["olives","honey","wine","local","products","gastronomy"]'::jsonb,
  '["kassandra","sithonia","mainland"]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '2026-02-25'
);

INSERT INTO blog_articles (
  slug, title_el, title_en, excerpt_el, excerpt_en,
  content_el, content_en, category, image_url, author,
  read_time_min, tags, related_area_slugs, related_beach_slugs,
  related_listing_slugs, related_article_slugs, published_at
) VALUES (
  'breakfast-spots-halkidiki',
  'Πού θα Φας Πρωινό στη Χαλκιδική',
  'Where to Have Breakfast in Halkidiki',
  'Από μπουγάτσα στα Μουδανιά μέχρι πρωινό δίπλα στη θάλασσα στη Σάρτη, ανακαλύψτε τα καλύτερα πρωινά.',
  'From bougatsa in Moudania to breakfast by the sea in Sarti, discover the best morning spots in Halkidiki.',
  E'## Πού θα Φας Πρωινό στη Χαλκιδική\n\nΤο πρωινό στη Χαλκιδική μπορεί να γίνει μια από τις πιο ωραίες στιγμές των διακοπών σας. Από παραδοσιακές μπουγάτσες μέχρι πρωινό με θέα τη θάλασσα, ιδού τα καλύτερα σημεία.\n\n## Μπουγάτσα στα Μουδανιά\n\nΤα Νέα Μουδανιά είναι η πύλη της Χαλκιδικής και εδώ θα βρείτε κάποια από τα καλύτερα μπουγατσατζίδικα. Η μπουγάτσα με κρέμα είναι η κλασική επιλογή, αλλά δοκιμάστε και με τυρί ή κιμά. Τα μπουγατσατζίδικα ανοίγουν από τις 6 το πρωί και είναι ιδανικά για ένα γρήγορο αλλά χορταστικό πρωινό πριν συνεχίσετε για τον προορισμό σας. Ζητήστε την μπουγάτσα ζεστή με αρκετή ζάχαρη και κανέλα.\n\n## Καφές στον Αφύτο\n\nΗ κεντρική πλατεία του Αφύτου, πάνω στον βράχο, είναι ίσως το πιο εντυπωσιακό μέρος για πρωινό καφέ στη Χαλκιδική. Πολλά καφέ ανοίγουν από νωρίς και σερβίρουν ελληνικό καφέ, freddo espresso και φρέσκους χυμούς. Η θέα στον Θερμαϊκό κόλπο είναι μαγευτική το πρωί, ειδικά πριν γεμίσει ο κόσμος. Ορισμένα καφέ σερβίρουν και σπιτικά γλυκά ή κρέπες.\n\n## Φούρνοι στον Νέο Μαρμαρά\n\nΟ Νέος Μαρμαράς, η πρωτεύουσα της Σιθωνίας, έχει εξαιρετικούς φούρνους. Πρωινό εδώ σημαίνει φρέσκια τυρόπιτα, σπανακόπιτα, κουλούρια Θεσσαλονίκης και ψωμί από παραδοσιακό φούρνο. Οι φούρνοι στο κέντρο ανοίγουν από τις 6:30 και μοσχοβολάνε. Πάρτε τη σακούλα σας και πηγαίνετε στο λιμάνι για πρωινό με θέα.\n\n## Πρωινό δίπλα στη Θάλασσα στη Σάρτη\n\nΗ Σάρτη στη Σιθωνία είναι γνωστή για τις μεγάλες παραλίες και τον χαλαρό ρυθμό ζωής. Στην παραλία θα βρείτε beach bars και καφέ που σερβίρουν πλήρες πρωινό: αυγά, τοστ, πανκέικ, γιαούρτι με μέλι και φρούτα. Αν θέλετε πρωινό με τα πόδια σας στην άμμο, η Σάρτη είναι η απάντηση.\n\n## Ζαχαροπλαστεία στην Αρναία\n\nΗ Αρναία, στην ορεινή Χαλκιδική, προσφέρει μια εντελώς διαφορετική εμπειρία πρωινού. Τα ζαχαροπλαστεία σερβίρουν σπιτικά γλυκά, γαλακτομπούρεκο, πορτοκαλόπιτα και τοπικές λιχουδιές. Σε συνδυασμό με τον ορεινό αέρα και τα πλατάνια, το πρωινό εδώ έχει ιδιαίτερη χάρη.\n\n## Συμβουλές\n\n- Ξεκινήστε νωρίς: τα καλύτερα προϊόντα εξαντλούνται\n- Δοκιμάστε τον ελληνικό καφέ μέτριο αν δεν τον έχετε πιει ποτέ\n- Ζητήστε φρέσκο χυμό πορτοκάλι, όχι χαρτοκούτι\n- Σε πολλά μαγαζιά η τυρόπιτα βγαίνει ζεστή γύρω στις 7-7:30\n- Αν μένετε σε σπίτι, επισκεφτείτε τις λαϊκές αγορές για φρούτα και γαλακτοκομικά',
  E'## Where to Have Breakfast in Halkidiki\n\nBreakfast in Halkidiki can become one of the best parts of your holiday. From traditional pastries to seaside coffee, here are the top spots.\n\n## Bougatsa in Moudania\n\nNea Moudania is the gateway to Halkidiki and home to some of the best bougatsa shops. This flaky pastry filled with custard cream is the classic choice, though cheese and minced meat versions are also available. Shops open at 6 AM and make a perfect, filling stop before continuing to your destination. Ask for it warm with plenty of sugar and cinnamon.\n\n## Coffee in Afytos\n\nThe central square in Afytos, perched on the cliff, is perhaps the most spectacular spot for morning coffee in Halkidiki. Several cafes open early, serving Greek coffee, freddo espresso, and fresh juices. The morning view across the Thermaic Gulf is stunning, especially before the crowds arrive. Some cafes also serve homemade pastries and crepes.\n\n## Bakeries in Neos Marmaras\n\nNeos Marmaras, the capital of Sithonia, has excellent bakeries. Breakfast here means fresh tyropita (cheese pie), spanakopita (spinach pie), Thessaloniki-style koulouri (sesame bread rings), and artisan bread. Central bakeries open at 6:30 AM. Grab your bag and head to the harbor to eat with a view.\n\n## Seaside Breakfast in Sarti\n\nSarti in Sithonia is known for its large beaches and relaxed pace. Beach bars and cafes along the shore serve full breakfasts including eggs, toast, pancakes, yogurt with honey and fruit. If you want breakfast with your feet in the sand, Sarti is the answer.\n\n## Pastry Shops in Arnea\n\nArnea, in mountainous Halkidiki, offers a completely different breakfast experience. Traditional pastry shops serve homemade galaktoboureko, orange cake, and local treats. Combined with the mountain air and plane trees, breakfast here has a special charm.\n\n## Tips\n\n- Start early: the best items sell out fast\n- Try Greek coffee medium-sweet if you have never had it\n- Order fresh squeezed orange juice, not from a carton\n- Hot tyropita comes out of the oven around 7-7:30 AM\n- Visit farmers markets for fruit and dairy if staying in a self-catered place',
  'food',
  '',
  'ChalkidikiHub',
  5,
  '["breakfast","bougatsa","coffee","morning","bakery"]'::jsonb,
  '["kassandra","sithonia","mainland"]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '2026-02-20'
);

