INSERT INTO blog_articles (
  slug, title_el, title_en, excerpt_el, excerpt_en,
  content_el, content_en, category, image_url, author,
  read_time_min, tags, related_area_slugs, related_beach_slugs,
  related_listing_slugs, related_article_slugs, published_at
) VALUES (
  'packing-list-halkidiki',
  'Τι να Πακετάρεις για Χαλκιδική: Η Πλήρης Λίστα',
  'What to Pack for Halkidiki: The Complete List',
  'Η πλήρης λίστα με ό,τι χρειάζεστε για τις διακοπές σας στη Χαλκιδική. Αντηλιακό, παπούτσια θαλάσσης και άλλα.',
  'The complete packing list for your Halkidiki holiday. Sunscreen, water shoes, and everything else you need.',
  E'## Τι να Πακετάρεις για Χαλκιδική\n\nΜια καλή προετοιμασία κάνει τη διαφορά στις διακοπές. Η Χαλκιδική έχει ορισμένες ιδιαιτερότητες που αξίζει να λάβετε υπόψη πριν φτιάξετε τη βαλίτσα σας.\n\n## Προστασία από τον Ήλιο\n\n- **Αντηλιακό SPF 50+**: Ο ήλιος στη Χαλκιδική είναι πολύ δυνατός από τον Ιούνιο μέχρι τον Σεπτέμβριο. Προτιμήστε αδιάβροχο αντηλιακό.\n- **Καπέλο**: Απαραίτητο, ειδικά για παιδιά. Ένα πλατύγυρο καπέλο προστατεύει πρόσωπο και λαιμό.\n- **Γυαλιά ηλίου**: Η αντανάκλαση από τη θάλασσα κουράζει τα μάτια. Πάρτε γυαλιά με προστασία UV400.\n- **Μπλούζα UV**: Ιδιαίτερα χρήσιμη για παιδιά που παίζουν ώρες στη θάλασσα.\n\n## Παραλία\n\n- **Παπούτσια θαλάσσης**: Απαραίτητα για τις βραχώδεις παραλίες και τους αχινούς. Ακόμα και σε αμμώδεις παραλίες, υπάρχουν βράχια στα ρηχά.\n- **Μάσκα και αναπνευστήρας**: Η Χαλκιδική έχει εξαιρετικό snorkeling. Αξίζει να φέρετε τα δικά σας αντί να νοικιάζετε.\n- **Ομπρέλα θαλάσσης**: Αν δεν θέλετε να πληρώνετε ξαπλώστρες, μια φορητή ομπρέλα είναι ιδανική.\n- **Φουσκωτά**: Για τα παιδιά, ένα μικρό φουσκωτό στρώμα ή κολυμβητική σανίδα.\n\n## Κουνούπια και Έντομα\n\n- **Αντικουνουπικό**: Τα κουνούπια στη Χαλκιδική μπορεί να είναι ενοχλητικά, ειδικά κοντά σε υγρότοπους και τα βράδια. Πάρτε σπρέι με DEET ή ικαριδίνη.\n- **Εντομοαπωθητικό πρίζας**: Για τα βράδια στο δωμάτιο, ειδικά αν μένετε σε σπίτι χωρίς σίτες.\n\n## Χρήματα και Κάρτες\n\n- **Μετρητά**: Πολλά μικρά μαγαζιά, καντίνες παραλίας και ταβέρνες σε χωριά δεν δέχονται κάρτα. Έχετε πάντα 50-100 ευρώ σε μετρητά.\n- **Κάρτα**: Visa και Mastercard γίνονται δεκτές στα περισσότερα σημεία. ATM υπάρχουν στους μεγάλους οικισμούς.\n\n## Τεχνολογία\n\n- **Ελληνική SIM κάρτα**: Αν δεν έχετε ευρωπαϊκό roaming, μια τοπική SIM κάρτα (Cosmote, Vodafone, Wind) κοστίζει 10-15 ευρώ με αρκετά data.\n- **Αντάπτορας πρίζας**: Η Ελλάδα χρησιμοποιεί πρίζες τύπου C και F (ευρωπαϊκές). Αν έρχεστε από UK ή ΗΠΑ, χρειάζεστε αντάπτορα.\n- **Powerbank**: Μια μπαταρία φόρτισης είναι χρήσιμη για μεγάλες μέρες στην παραλία ή εκδρομές.\n- **Αδιάβροχη θήκη κινητού**: Για φωτογραφίες στη θάλασσα χωρίς κίνδυνο.\n\n## Ρούχα\n\n- **Ελαφριά ρούχα**: Βαμβακερά και λινά ρούχα για τη ζέστη\n- **Ζακέτα**: Ακόμα και το καλοκαίρι, τα βράδια μπορεί να δροσίσει, ειδικά κοντά στη θάλασσα\n- **Βολικά παπούτσια**: Για πεζοπορία σε μονοπάτια και σοκάκια\n- **Μαγιό (2-3)**: Ένα στεγνό μαγιό κάνει τη διαφορά\n\n## Φαρμακείο\n\n- **Βασικό φαρμακείο**: Παυσίπονα, αντιδιαρροϊκά, πλαστικά τραυμάτων\n- **Φάρμακα ναυτίας**: Αν σκοπεύετε να κάνετε βόλτα με σκάφος\n- **Αλοιφή για εγκαύματα**: After-sun ή Panthenol\n- **Τσιμπήματα αχινού**: Μια τσιμπίδα και ξίδι μπορεί να σας σώσουν\n\n## Τι ΔΕΝ Χρειάζεστε\n\n- Επίσημα ρούχα: Η Χαλκιδική είναι casual\n- Πετσέτα θαλάσσης: Τα περισσότερα καταλύματα παρέχουν\n- Παιχνίδια θαλάσσης: Αγοράζονται εύκολα και φθηνά εκεί',
  E'## What to Pack for Halkidiki\n\nGood preparation makes all the difference on holiday. Halkidiki has some specifics worth considering before you pack.\n\n## Sun Protection\n\n- **SPF 50+ sunscreen**: The sun is very strong from June to September. Choose a waterproof formula.\n- **Wide-brimmed hat**: Essential, especially for children.\n- **UV400 sunglasses**: Sea reflection is intense.\n- **UV swim shirt**: Very useful for children spending hours in the water.\n\n## Beach Essentials\n\n- **Water shoes**: Essential for rocky beaches and sea urchin protection. Even sandy beaches can have rocks in shallow areas.\n- **Snorkel mask and tube**: Halkidiki has excellent snorkeling, and bringing your own is better than renting.\n- **Portable beach umbrella**: Save money by skipping sunbed rentals.\n- **Inflatables**: A small float or swimming board for kids.\n\n## Mosquito Protection\n\n- **DEET or icaridin repellent**: Mosquitoes can be bothersome near wetlands and in the evenings.\n- **Plug-in repellent**: For nights in rooms without screens.\n\n## Money\n\n- **Cash**: Many small shops, beach canteens, and village tavernas do not accept cards. Always carry 50-100 euros in cash.\n- **Cards**: Visa and Mastercard are widely accepted. ATMs exist in larger settlements.\n\n## Technology\n\n- **Greek SIM card**: If you lack European roaming, a local SIM (Cosmote, Vodafone, Wind) costs 10-15 euros with good data.\n- **Power adapter**: Greece uses type C and F plugs (European). UK and US visitors need an adapter.\n- **Power bank**: Useful for long beach days or excursions.\n- **Waterproof phone case**: For underwater photos without risk.\n\n## Clothing\n\n- Light cotton and linen clothes for the heat\n- A light jacket for cooler evenings by the sea\n- Comfortable walking shoes for trails and village lanes\n- 2-3 swimsuits so you always have a dry one\n\n## First Aid\n\n- Basic painkillers, plasters, anti-diarrhea medication\n- Seasickness tablets if planning boat trips\n- After-sun cream or Panthenol for sunburn\n- Tweezers and vinegar for sea urchin spines\n\n## What You Do NOT Need\n\n- Formal clothes: Halkidiki is casual\n- Beach towels: Most accommodations provide them\n- Beach toys: Easily and cheaply bought locally',
  'tips',
  '',
  'ChalkidikiHub',
  5,
  '["packing","tips","preparation","summer","travel","essentials"]'::jsonb,
  '["kassandra","sithonia","athos","mainland"]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '2026-02-10'
);

INSERT INTO blog_articles (
  slug, title_el, title_en, excerpt_el, excerpt_en,
  content_el, content_en, category, image_url, author,
  read_time_min, tags, related_area_slugs, related_beach_slugs,
  related_listing_slugs, related_article_slugs, published_at
) VALUES (
  'halkidiki-september-guide',
  'Σεπτέμβριος στη Χαλκιδική: Ο Κρυφός Θησαυρός',
  'September in Halkidiki: The Hidden Treasure',
  'Γιατί ο Σεπτέμβριος είναι ο ιδανικός μήνας για Χαλκιδική. Ζεστή θάλασσα, λιγότερος κόσμος, χαμηλές τιμές.',
  'Why September is the ideal month for Halkidiki. Warm sea, fewer crowds, lower prices, and perfect weather.',
  E'## Σεπτέμβριος στη Χαλκιδική: Γιατί Είναι ο Καλύτερος Μήνας\n\nΑν ψάχνετε τον ιδανικό μήνα για Χαλκιδική, ο Σεπτέμβριος είναι η απάντηση. Ο κόσμος φεύγει, η θάλασσα παραμένει ζεστή, και οι τιμές πέφτουν. Ιδού γιατί αξίζει.\n\n## Η Θάλασσα\n\nΗ θερμοκρασία της θάλασσας τον Σεπτέμβριο κυμαίνεται μεταξύ 24 και 26 βαθμών Κελσίου, ιδανική για μεγάλες ώρες κολύμβησης. Στην πραγματικότητα, η θάλασσα τον Σεπτέμβριο μπορεί να είναι πιο ζεστή από ό,τι τον Ιούνιο, επειδή έχει θερμανθεί σε όλη τη διάρκεια του καλοκαιριού.\n\n## Ο Καιρός\n\nΗ θερμοκρασία του αέρα πέφτει ελαφρώς σε σχέση με τον Αύγουστο, με μέσο όρο 26-30 βαθμούς. Ο ήλιος είναι λιγότερο καυτός, κάτι που κάνει την παραλία πιο ευχάριστη. Ωστόσο, μπορεί να εμφανιστούν σύντομες καταιγίδες, ειδικά στο τέλος του μήνα. Συνήθως περνάνε γρήγορα.\n\n## Λιγότερος Κόσμος\n\nΤο μεγάλο πλεονέκτημα. Οι ελληνικές διακοπές τελειώνουν στις 31 Αυγούστου, οπότε οι παραλίες αδειάζουν δραματικά μετά την 1η Σεπτεμβρίου. Παραλίες που τον Αύγουστο είναι γεμάτες, τον Σεπτέμβριο τις απολαμβάνετε σχεδόν μόνοι. Ακόμα και δημοφιλή μέρη όπως η Σάνη, η Σάρτη και η Βουρβουρού είναι πολύ πιο ήρεμα.\n\n## Χαμηλότερες Τιμές\n\nΟι τιμές σε καταλύματα πέφτουν 30-50% σε σχέση με τον Αύγουστο. Ένα δωμάτιο που κοστίζει 120 ευρώ τον Αύγουστο μπορεί να βρεθεί στα 60-80 ευρώ τον Σεπτέμβριο. Επίσης, δεν χρειάζεται να κρατήσετε τόσο νωρίς.\n\n## Τι Είναι Ανοιχτό\n\nΤο πρώτο δεκαπενθήμερο του Σεπτεμβρίου, σχεδόν τα πάντα λειτουργούν κανονικά: εστιατόρια, beach bars, σούπερ μάρκετ, ενοικιαζόμενα. Το δεύτερο δεκαπενθήμερο, κάποια εποχικά μαγαζιά αρχίζουν να κλείνουν, ειδικά στις πιο απομακρυσμένες περιοχές. Ωστόσο, οι κεντρικοί οικισμοί (Καλλιθέα, Νικήτη, Νέος Μαρμαράς, Σάρτη) παραμένουν ζωντανοί.\n\n## Τι Κλείνει\n\n- Κάποια beach bars κλείνουν μετά τις 15 Σεπτεμβρίου\n- Ορισμένα water sports κλείνουν τέλη Αυγούστου\n- Τα πλοία κρουαζιέρας στο Άγιο Όρος μειώνουν δρομολόγια αλλά συνεχίζουν\n- Λίγα μαγαζιά σε μικρά χωριά κλείνουν νωρίς\n\n## Ιδανικές Δραστηριότητες\n\n- **Πεζοπορία**: Η θερμοκρασία είναι τέλεια για περπάτημα στη φύση\n- **Ποδήλατο**: Λιγότερη κίνηση στους δρόμους\n- **Κρουαζιέρα**: Πιο ήρεμη θάλασσα, λιγότερος κόσμος στα πλοία\n- **Τρύγος**: Η εποχή του τρύγου στα αμπέλια. Αν βρείτε ανοιχτό οινοποιείο, η εμπειρία είναι μοναδική\n- **Φωτογραφία**: Το φως τον Σεπτέμβριο είναι χρυσό και ιδανικό για φωτογραφίες\n\n## Για Ποιον Είναι ο Σεπτέμβριος\n\n- Ζευγάρια που θέλουν ρομαντισμό χωρίς κόσμο\n- Οικογένειες με παιδιά που δεν πάνε ακόμα σχολείο\n- Συνταξιούχοι που αναζητούν ησυχία\n- Ψηφιακοί νομάδες που θέλουν Wi-Fi και θάλασσα',
  E'## September in Halkidiki: Why It Is the Best Month\n\nIf you are looking for the perfect month to visit Halkidiki, September is the answer. Crowds leave, the sea stays warm, and prices drop significantly.\n\n## The Sea\n\nSea temperature in September ranges between 24 and 26 degrees Celsius, ideal for long swimming sessions. The sea can actually be warmer in September than in June because it has been heating up all summer.\n\n## Weather\n\nAir temperature drops slightly compared to August, averaging 26-30 degrees. The sun is less fierce, making beach time more enjoyable. Brief storms may appear, especially late in the month, but they pass quickly.\n\n## Fewer Crowds\n\nThe biggest advantage. Greek holidays end on August 31, so beaches empty dramatically after September 1. Beaches packed in August become almost private in September. Even popular spots like Sani, Sarti, and Vourvourou are much calmer.\n\n## Lower Prices\n\nAccommodation prices drop 30-50% compared to August. A room costing 120 euros in August can be found for 60-80 euros in September. Early booking is also less critical.\n\n## What Is Open\n\nThe first half of September sees almost everything running normally: restaurants, beach bars, supermarkets, and rentals. In the second half, some seasonal businesses start closing in remote areas, but main settlements (Kallithea, Nikiti, Neos Marmaras, Sarti) remain lively.\n\n## What Closes\n\n- Some beach bars close after September 15\n- Certain water sports stop in late August\n- Mount Athos cruise ships reduce but continue sailing\n- A few shops in small villages close early\n\n## Ideal Activities\n\n- **Hiking**: Perfect temperatures for nature walks\n- **Cycling**: Less traffic on the roads\n- **Cruises**: Calmer sea and fewer passengers\n- **Grape harvest**: Vineyard season offers unique winery experiences\n- **Photography**: September light is golden and ideal\n\n## Who Is September For\n\n- Couples seeking romance without crowds\n- Families with pre-school children\n- Retirees looking for tranquility\n- Digital nomads wanting Wi-Fi and sea',
  'tips',
  '',
  'ChalkidikiHub',
  6,
  '["september","off-season","autumn","quiet","affordable","warm-sea"]'::jsonb,
  '["kassandra","sithonia"]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '2026-02-05'
);

