INSERT INTO blog_articles (
  slug, title_el, title_en, excerpt_el, excerpt_en,
  content_el, content_en, category, image_url, author,
  read_time_min, tags, related_area_slugs, related_beach_slugs,
  related_listing_slugs, related_article_slugs, published_at
) VALUES (
  'aristotle-halkidiki',
  'Ο Αριστοτέλης και η Χαλκιδική: Ιστορία και Μνημεία',
  'Aristotle and Halkidiki: History and Monuments',
  'Ακολουθήστε τα βήματα του Αριστοτέλη στη Χαλκιδική. Στάγειρα, Πάρκο Αριστοτέλη και αρχαία μνημεία.',
  'Follow Aristotle''s footsteps in Halkidiki. Stagira, Aristotle''s Park, and ancient monuments to explore.',
  E'## Ο Αριστοτέλης και η Χαλκιδική\n\nΗ Χαλκιδική δεν είναι μόνο παραλίες και τουρισμός. Είναι η γενέτειρα ενός από τους μεγαλύτερους φιλοσόφους που γνώρισε ποτέ ο κόσμος: του Αριστοτέλη. Η σύνδεσή του με αυτόν τον τόπο προσδίδει βάθος και νόημα σε κάθε επίσκεψη.\n\n## Γέννηση στα Στάγειρα\n\nΟ Αριστοτέλης γεννήθηκε το 384 π.Χ. στα Στάγειρα, μια αρχαία πόλη στη βορειοανατολική Χαλκιδική. Ο πατέρας του, Νικόμαχος, ήταν προσωπικός γιατρός του βασιλιά Αμύντα Γ'' της Μακεδονίας. Αυτή η σύνδεση με τη μακεδονική αυλή θα σημάδευε τη ζωή του Αριστοτέλη, καθώς αργότερα έγινε δάσκαλος του Μεγάλου Αλεξάνδρου.\n\n## Ο Αρχαιολογικός Χώρος των Σταγείρων\n\nΤα αρχαία Στάγειρα βρίσκονται κοντά στη σημερινή Ολυμπιάδα, σε ένα λόφο με θέα τον κόλπο του Στρυμώνα. Ο αρχαιολογικός χώρος περιλαμβάνει:\n\n- **Τείχη της πόλης**: Σωζόμενα τμήματα των αρχαίων τειχών\n- **Ακρόπολη**: Στην κορυφή του λόφου, με εντυπωσιακή θέα\n- **Αγορά**: Τα ερείπια της αρχαίας αγοράς, κέντρο της δημόσιας ζωής\n- **Υδραγωγείο**: Αρχαίο σύστημα ύδρευσης\n\nΗ είσοδος είναι ελεύθερη. Η επίσκεψη διαρκεί περίπου 1-1,5 ώρα. Φοράτε βολικά παπούτσια γιατί το έδαφος είναι ανώμαλο.\n\n## Το Πάρκο του Αριστοτέλη\n\nΤο Πάρκο του Αριστοτέλη βρίσκεται κοντά στο χωριό Στάγειρα (όχι τον αρχαιολογικό χώρο) και είναι ένα μοναδικό υπαίθριο μουσείο αφιερωμένο στη φυσική φιλοσοφία. Τα αλληλεπιδραστικά εκθέματα επιδεικνύουν αρχές που μελέτησε ο Αριστοτέλης:\n\n- **Οπτικοί δίσκοι**: Αποδεικνύουν οπτικές ψευδαισθήσεις\n- **Ηλιακό ρολόι**: Δείχνει την ώρα με ακρίβεια\n- **Εκκρεμές**: Επιδεικνύει τις αρχές της κίνησης\n- **Πρίσμα**: Αναλύει το φως στα χρώματα του ουράνιου τόξου\n- **Κομπρεσέρ αέρα**: Φυσικό φαινόμενο με τη δύναμη του αέρα\n\nΤο πάρκο είναι εξαιρετικό για παιδιά. Η είσοδος είναι ελεύθερη.\n\n## Το Άγαλμα του Αριστοτέλη\n\nΣτα σύγχρονα Στάγειρα υπάρχει ένα μαρμάρινο άγαλμα του Αριστοτέλη σε κεντρικό σημείο. Είναι ένα δημοφιλές σημείο φωτογραφίας και ένα σύμβολο τιμής στον μεγάλο φιλόσοφο.\n\n## Αριστοτέλης και Μέγας Αλέξανδρος\n\nΗ σχέση μεταξύ Αριστοτέλη και Μεγάλου Αλεξάνδρου είναι μια από τις πιο σημαντικές στην ιστορία. Ο Φίλιππος Β'' κάλεσε τον Αριστοτέλη να γίνει δάσκαλος του γιου του στη Μίεζα, κοντά στη Νάουσα. Για τρία χρόνια, ο Αριστοτέλης δίδαξε τον νεαρό Αλέξανδρο φιλοσοφία, επιστήμες, ιατρική και λογοτεχνία. Σε αντάλλαγμα, ο Φίλιππος ανοικοδόμησε τα Στάγειρα που είχε καταστρέψει νωρίτερα.\n\n## Φιλοσοφικά Ρητά\n\nΠεριπατώντας στη Χαλκιδική, αξίζει να θυμάστε μερικές σκέψεις του Αριστοτέλη που εμπνέουν μέχρι σήμερα. Ο φιλόσοφος πίστευε στην εμπειρία ως πηγή γνώσης και στη φύση ως δάσκαλο. Αυτή η φιλοσοφία αντικατοπτρίζεται τέλεια στο φυσικό κάλλος της Χαλκιδικής.\n\n## Πρακτικές Πληροφορίες Επίσκεψης\n\n- **Πρόσβαση**: Τα Στάγειρα απέχουν 100 χλμ. από τη Θεσσαλονίκη\n- **Συνδυάστε**: Με επίσκεψη στην Ολυμπιάδα για κολύμπι\n- **Ώρες**: Ο αρχαιολογικός χώρος είναι ανοιχτός όλη τη μέρα\n- **Καλύτερη ώρα**: Πρωί ή απόγευμα για να αποφύγετε τη ζέστη\n- **Διάρκεια**: 2-3 ώρες για αρχαιολογικό χώρο + πάρκο',
  E'## Aristotle and Halkidiki\n\nHalkidiki is the birthplace of one of the greatest philosophers the world has ever known: Aristotle. His connection to this land adds depth and meaning to every visit.\n\n## Birth in Stagira\n\nAristotle was born in 384 BC in Stagira, an ancient city in northeastern Halkidiki. His father, Nicomachus, was personal physician to King Amyntas III of Macedon. This royal connection shaped Aristotle''s life, as he later became the tutor of Alexander the Great.\n\n## The Archaeological Site\n\nAncient Stagira lies near modern Olympiada, on a hill overlooking the Strymonikos Gulf. The site includes preserved city walls, an acropolis with impressive views, the ancient agora (marketplace), and a water supply system. Entry is free and a visit takes about 1-1.5 hours. Wear comfortable shoes as the terrain is uneven.\n\n## Aristotle''s Park\n\nLocated near the modern village of Stagira, this unique open-air museum is dedicated to natural philosophy. Interactive exhibits demonstrate principles Aristotle studied: optical discs showing illusions, a sundial, a pendulum, a prism breaking light into rainbow colors, and air compression devices. The park is excellent for children and entry is free.\n\n## The Statue\n\nA marble statue of Aristotle stands in central modern Stagira, serving as a popular photo spot and a symbol of honor to the great philosopher.\n\n## Aristotle and Alexander the Great\n\nPhilip II invited Aristotle to tutor his son Alexander at Mieza, near Naoussa. For three years, Aristotle taught the young prince philosophy, sciences, medicine, and literature. In return, Philip rebuilt Stagira, which he had previously destroyed.\n\n## Visiting Information\n\n- **Access**: Stagira is 100 km from Thessaloniki\n- **Combine with**: Swimming at Olympiada beach\n- **Hours**: The archaeological site is open all day\n- **Best time**: Morning or afternoon to avoid midday heat\n- **Duration**: 2-3 hours for the site plus the park',
  'culture',
  '',
  'ChalkidikiHub',
  7,
  '["aristotle","stagira","philosophy","history","ancient","culture"]'::jsonb,
  '["athos","mainland"]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '2026-01-25'
);

INSERT INTO blog_articles (
  slug, title_el, title_en, excerpt_el, excerpt_en,
  content_el, content_en, category, image_url, author,
  read_time_min, tags, related_area_slugs, related_beach_slugs,
  related_listing_slugs, related_article_slugs, published_at
) VALUES (
  'orthodox-monasteries-halkidiki',
  'Ορθόδοξα Μοναστήρια εκτός Αγίου Όρους',
  'Orthodox Monasteries Outside Mount Athos',
  'Μοναστήρια και εκκλησίες στη Χαλκιδική που μπορεί να επισκεφτεί ο καθένας, χωρίς περιορισμούς πρόσβασης.',
  'Monasteries and churches in Halkidiki that everyone can visit, with no access restrictions or permits needed.',
  E'## Ορθόδοξα Μοναστήρια εκτός Αγίου Όρους\n\nΤο Άγιο Όρος είναι ο πιο γνωστός θρησκευτικός προορισμός της Χαλκιδικής, αλλά η πρόσβαση είναι περιορισμένη: μόνο άνδρες με ειδική άδεια. Ωστόσο, η Χαλκιδική κρύβει πολλά μοναστήρια, εκκλησίες και πνευματικά μνημεία που μπορεί να επισκεφτεί ο καθένας.\n\n## Μονή Ζυγού\n\nΤα ερείπια της Μονής Ζυγού βρίσκονται κοντά στη Φράγκοκάστρο, ακριβώς στα σύνορα του Αγίου Όρους. Πρόκειται για ένα από τα πιο σημαντικά βυζαντινά μνημεία της Χαλκιδικής. Η μονή ιδρύθηκε τον 10ο αιώνα και εγκαταλείφθηκε τον 12ο αιώνα. Οι αρχαιολογικές ανασκαφές αποκάλυψαν τον καθολικό ναό, κελιά μοναχών, αποθήκες και δεξαμενή νερού.\n\n- **Πρόσβαση**: Ελεύθερη, ανοιχτή σε όλους\n- **Τοποθεσία**: 5 χλμ. πριν τα σύνορα του Αγίου Όρους\n- **Αξία**: Σπάνιο βυζαντινό μνημείο, λίγο γνωστό στους τουρίστες\n\n## Θέα στο Ξενοφώντος\n\nΑπό την ακτή κοντά στην Ουρανούπολη, μπορείτε να δείτε τη Μονή Ξενοφώντος, ένα από τα 20 κυρίαρχα μοναστήρια του Αγίου Όρους. Η θέα είναι εντυπωσιακή, με το μοναστήρι να ορθώνεται πάνω στη θάλασσα. Αν και δεν μπορείτε να μπείτε χωρίς άδεια, η θέα από μακριά, ειδικά κατά το ηλιοβασίλεμα, αξίζει.\n\n## Εκκλησίες στην Παλιά Νικήτη\n\nΗ Παλιά Νικήτη είναι ο παραδοσιακός οικισμός πάνω από τη σύγχρονη Νικήτη στη Σιθωνία. Τα πέτρινα σπίτια και τα στενά σοκάκια κρύβουν αρκετές εκκλησίες αξιοσημείωτου αρχιτεκτονικού ενδιαφέροντος:\n\n- **Εκκλησία Αγίου Νικήτα**: Η κεντρική εκκλησία του χωριού, με ξύλινο τέμπλο\n- **Εκκλησία Κοίμησης Θεοτόκου**: Με τοιχογραφίες του 19ου αιώνα\n- **Μικρά εξωκκλήσια**: Διάσπαρτα στους ελαιώνες γύρω από το χωριό\n\nΗ Παλιά Νικήτη είναι ιδανική για ήρεμο περίπατο και φωτογραφίες.\n\n## Μονή στην Αρναία\n\nΗ περιοχή της Αρναίας, στην ορεινή Χαλκιδική, φιλοξενεί μικρά μοναστήρια και εξωκκλήσια μέσα στα δάση. Η εκκλησία της Αγίας Παρασκευής, στο κέντρο του χωριού, είναι ένα εντυπωσιακό δείγμα μακεδονικής αρχιτεκτονικής. Η ατμόσφαιρα στην Αρναία είναι γαλήνια, μακριά από τον τουριστικό θόρυβο.\n\n## Μεταβυζαντινές Εκκλησίες\n\nΣε πολλά χωριά της Χαλκιδικής θα βρείτε μεταβυζαντινές εκκλησίες με αξιόλογες αγιογραφίες:\n\n- **Πολύγυρος**: Ο ναός του Αγίου Νικολάου με σημαντικές εικόνες\n- **Αρναία**: Αγία Παρασκευή, εντυπωσιακός ναός με ξυλόγλυπτο τέμπλο\n- **Ιερισσός**: Εκκλησίες που συνδέονται με την ιστορία του Αγίου Όρους\n\n## Πνευματικός Τουρισμός\n\nΓια μια ολοκληρωμένη πνευματική εμπειρία στη Χαλκιδική:\n\n1. Ξεκινήστε από τη Μονή Ζυγού το πρωί\n2. Συνεχίστε στην Ουρανούπολη για θέα στο Άγιο Όρος\n3. Πάρτε την κρουαζιέρα γύρω από το Άγιο Όρος\n4. Επισκεφτείτε την Παλιά Νικήτη το απόγευμα\n5. Κλείστε τη μέρα στην Αρναία για δείπνο\n\n## Σεβασμός στους Ιερούς Χώρους\n\n- Ντυθείτε κατάλληλα: Μακρύ παντελόνι και καλυμμένοι ώμοι\n- Μιλήστε χαμηλόφωνα μέσα στις εκκλησίες\n- Ζητήστε άδεια πριν φωτογραφίσετε εσωτερικούς χώρους\n- Σεβαστείτε τις ώρες λειτουργίας και τις τελετές',
  E'## Orthodox Monasteries Outside Mount Athos\n\nMount Athos is Halkidiki''s most famous religious destination, but access is restricted to men with special permits. However, Halkidiki holds many monasteries, churches, and spiritual monuments that everyone can visit.\n\n## Zygou Monastery\n\nThe ruins of Zygou Monastery lie near Fragkokastro, right at the border of Mount Athos. It is one of Halkidiki''s most important Byzantine monuments. Founded in the 10th century and abandoned in the 12th, excavations revealed the main church, monks'' cells, storerooms, and a water cistern.\n\n- **Access**: Free and open to everyone\n- **Location**: 5 km before the Mount Athos border\n- **Value**: A rare Byzantine monument little known to tourists\n\n## View of Xenofontos Monastery\n\nFrom the coast near Ouranoupolis, you can see Xenofontos Monastery, one of the 20 ruling monasteries of Mount Athos. The view is striking, with the monastery rising above the sea. While you cannot enter without a permit, the sight from afar, especially at sunset, is worth the trip.\n\n## Churches in Old Nikiti\n\nOld Nikiti is the traditional settlement above modern Nikiti in Sithonia. Its stone houses and narrow lanes hide several churches of notable architectural interest, including the Church of Agios Nikitas with a wooden iconostasis and the Church of the Dormition with 19th-century frescoes. Small chapels are scattered among the surrounding olive groves.\n\n## Arnea Monastery Area\n\nThe Arnea area in mountainous Halkidiki hosts small monasteries and forest chapels. The Church of Agia Paraskevi in the village center is an impressive example of Macedonian architecture. The atmosphere is peaceful, far from tourist noise.\n\n## Post-Byzantine Churches\n\nMany Halkidiki villages contain post-Byzantine churches with notable icon paintings:\n- **Polygyros**: Church of Agios Nikolaos with important icons\n- **Arnea**: Agia Paraskevi with an elaborate wooden iconostasis\n- **Ierissos**: Churches connected to Mount Athos history\n\n## Spiritual Tourism Route\n\nFor a complete spiritual experience: start at Zygou Monastery in the morning, continue to Ouranoupolis for views of Mount Athos, take the cruise, visit Old Nikiti in the afternoon, and end with dinner in Arnea.\n\n## Respecting Sacred Spaces\n\n- Dress appropriately: long trousers and covered shoulders\n- Speak quietly inside churches\n- Ask permission before photographing interiors\n- Respect opening hours and ceremonies',
  'culture',
  '',
  'ChalkidikiHub',
  7,
  '["monasteries","orthodox","religion","history","churches","spiritual"]'::jsonb,
  '["athos","sithonia","mainland"]'::jsonb,
  '[]'::jsonb,
